51单片机串口模式下的编程实践
嵌入式领域工作5年，说实话，自己对嵌入式设备硬件还是在一知半解状态，工作中接触最多的就是硬件编程了，什么NIOS，FPGA，CPLD，I2C，SMI，EEPROM等专业词汇满天飞。而自己对这些元器件或者接口只知道大概作用，具体为什么有这种特性也不了解。好在我负责嵌入式软件层面的东西，对硬件东西不需要了解太深。最近在某宝上买了个51单片机，赠送了一大堆视频，主要讲解了一些器件的电气特性及工作原理，我不懂电路分析，也是懂非懂的，视频中讲解了如何点灯，如何数码管显示，如何获取温度，串口通讯等内容。
我自己也开始慢慢研究如何在设备上调试写代码，结合我5年代码的功力，觉得应该在串口模式下把这些功能集中在一个程序中。简单一点说就是，利用串口发送对应的指令与单片机通讯，单片机内部解析后做相应的动作。代码本身不太难，不过由于空ROM空间有限，如何在有限的空间上发挥设备的最大作用也是一个挑战点，需要对代码适当作优化。我们可以把常用的表驱动法，FSM有限状态机等编程模式带入到这个实验中去（这些奇技淫巧在项目代码中也最为常见）。下面是C代码实现（51单片机没有操作系统，直接对地址进行操作）：
typedef unsigned int u16;     //对数据类型进行声明定义
typedef unsigned char u8;

/*******************************************************************************
* 函数名         :UsartInit()
* 函数功能         :设置串口
* 输入           : 无
* 输出             : 无
*******************************************************************************/
void UsartInit()
{
    SCON = 0X50;            //设置为工作方式1
    TMOD = 0X20;            //设置计数器工作方式2
    PCON = 0X80;            //波特率加倍
    TH1 = 0XF3;             //计数器初始值设置，注意波特率是4800的
    TL1= 0XF3;
    ES = 1;                     //打开接收中断
    EA = 1;                     //打开总中断
    TR1 = 1;                    //打开计数器
}

void Uart232SendByte(u8 data)
{
    SBUF = data;//将接收到的数据放入到发送寄存器
    while(!TI); //等待发送数据完成
    TI = 0;     //清除发送完成标志位
}

void Uart232SendMsg(char *msg)
{
    u8 length = strlen(msg);
    u8 index;
    if (length == 0)
    {
        return;
    }

    for (index = 0; index &lt; length; index++)
    {
        Uart232SendByte(msg[index]);
    }

    Uart232SendByte(&#39;\n&#39;);
}

typedef void(*UART_FUNC)(char *para1, char *para2) __reentrant;


typedef struct tagUart232FuncMap
{
    const char *cmd;
    UART_FUNC func;
} Uart232FuncMap;

#define LED P2
//n数据进行左移s操作,数据位宽为t

#define ROTATE_LEFT(n, s, t)  ((n &lt;&lt; s) | (n &gt;&gt; (t - s)))
#define ROTATE_RIGHT(n, s, t) ((n &gt;&gt; s) | (n &lt;&lt; (t - s)))

__xdata u8 buffer[48] = {0};

void Uart232LedProc(char *para1, char *para2) __reentrant
{
    //led点灯动作
    __xdata static u8 ledValue = 0x1;
    LED = ledValue;
    LED = ROTATE_LEFT(LED, 1, 8);
    ledValue = LED;
    sprintf(buffer, &quot;led operation, para1 = %s, para2 = %s\n&quot;, para1, para2);
    Uart232SendMsg(buffer);
}


#define DIGIT_MAXSIZE 8

void addProc(const char *para1, const char *para2) __reentrant
{
    u8 a[DIGIT_MAXSIZE] = {0};
    u8 b[DIGIT_MAXSIZE] = {0};
    u8 length1 = strlen(para1);
    u8 length2 = strlen(para2);
    u8 index = 0;
    u8 carry = 0;
    u8 offset = 0;

    for (index = 0; index &lt; length1 &amp;&amp; index &lt; DIGIT_MAXSIZE; index++)
    {
        a[index] = para1[length1 - 1 - index] - &#39;0&#39;;
    }

    for (index = 0; index &lt; length2 &amp;&amp; index &lt; DIGIT_MAXSIZE; index++)
    {
        b[index] = para2[length2 - 1 - index] - &#39;0&#39;;
    }

    for (index = 0; index &lt; DIGIT_MAXSIZE; index++)
    {
        a[index] = a[index] + b[index] + carry;
        carry = a[index] / 10;
        a[index] %= 10;
    }



    offset += sprintf(buffer + offset, &quot;%s + %s = &quot;, para1, para2);
    //判断index不为负数
    for (index = DIGIT_MAXSIZE - 1; (index &amp; 0x80) != 0x80 ; index--)
    {
        if(a[index]) //找到第一个最高位不为0，找不到时，index为-1
        {
            break;
        }
    }

    if ((index &amp; 0x80) == 0x80) //index可能为负数,先排除掉
    {
        offset += sprintf(buffer + offset, &quot;%c&quot;, &#39;0&#39;);
    }

    while ((index &amp; 0x80) != 0x80)
    {
       offset += sprintf(buffer + offset, &quot;%c&quot;, a[index] + &#39;0&#39;);
       index--;
    }
    Uart232SendMsg(buffer);
}

void Uart232AddProc(char *para1, char *para2) __reentrant
{
    addProc(para1, para2);
}

#define LSA P2_2
#define LSB P2_3
#define LSC P2_4
#define NUM 8
__code u8 digitsMap[10] = {0x3f,0x06,0x5b,0x4f,0x66,0x6d,0x7d,0x07,0x7f,0x6f};

void DigDisplay() __reentrant
{
    __xdata static u8 i = 0;
    i %= 8;
    P0 = 0; //先消失，后显示
    switch(i % 8)    //位选，选择点亮的数码管，
    {
    case(0):
        LSA=0;
        LSB=0;
        LSC=0;
        break;//显示第0位
    case(1):
        LSA=1;
        LSB=0;
        LSC=0;
        break;//显示第1位
    case(2):
        LSA=0;
        LSB=1;
        LSC=0;
        break;//显示第2位
    case(3):
        LSA=1;
        LSB=1;
        LSC=0;
        break;//显示第3位
    case(4):
        LSA=0;
        LSB=0;
        LSC=1;
        break;//显示第4位
    case(5):
        LSA=1;
        LSB=0;
        LSC=1;
        break;//显示第5位
    case(6):
        LSA=0;
        LSB=1;
        LSC=1;
        break;//显示第6位
    case(7):
        LSA=1;
        LSB=1;
        LSC=1;
        break;//显示第7位
    }
    P0=digitsMap[i];//发送段码
    i++;
}


void Uart232DigitProc(char *para1, char *para2) __reentrant
{
    sprintf(buffer, &quot;digit operation, para1 = %s, para2 = %s\n&quot;, para1, para2);
    DigDisplay();
    Uart232SendMsg(buffer);
}

void Uart232SetTimerProc(char *para1, char *para2) __reentrant
{
    sprintf(buffer, &quot;timer operation, para1 = %s, para2 = %s\n&quot;, para1, para2);
    Uart232SendMsg(buffer);
}

__code Uart232FuncMap g_usartFunMap[] =
{
    {&quot;led&quot;,   Uart232LedProc},
    {&quot;add&quot;,   Uart232AddProc},
    {&quot;digit&quot;,   Uart232DigitProc},
    {&quot;timer&quot;,   Uart232SetTimerProc},
};

void Uart232CmdProc(char *cmd, char *para1, char *para2)
{
    u8 index;

    UART_FUNC cmdFun = NULL;

    for (index = 0; index &lt; sizeof(g_usartFunMap)/sizeof(g_usartFunMap[0]); index++)
    {
        if (strcmp(cmd, g_usartFunMap[index].cmd) == 0) //如果相同的话
        {
            cmdFun = g_usartFunMap[index].func;
            break;
        }
    }

    if (index == sizeof(g_usartFunMap)/sizeof(g_usartFunMap[0])) //没有找到
    {
        Uart232SendMsg(&quot;cmd not found\n&quot;);
        return;
    }

    cmdFun(para1, para2); //调用函数

}

#define BUFFER_MAXSIZE 16
u8 g_ucPos = 0;
u8 g_ucValidFlag = 0;
u8 receiveData[BUFFER_MAXSIZE] = {0};

//提取参数, 最多只支持2个参数
u8 Uart232ExtractParams(char *str, char *cmd, char *para1, char *para2) __critical
{
    u8 index = 0;
    char *ptr = NULL;
    const char *delim = &quot; &quot;;
    char *para[3] = {cmd, para1, para2};
    for(ptr = strtok(str, delim); ptr != NULL; ptr = strtok(NULL, delim))
    {
        memcpy(para[index++], ptr, BUFFER_MAXSIZE);
    }

    if (index &gt; 3)
    {
        return 0xff;
    }

    return 0;

}


void Usart() __interrupt 4
{
    u8 temp;
    while (RI == 1)
    {
        RI = 0;//清除接收中断标志位
        temp = SBUF;//接收到的数据
        if (temp == &#39;\r&#39; || temp == &#39;\n&#39;)
        {
            g_ucValidFlag = 1;
            g_ucPos = 0; //清除位置
            break;
        }
        receiveData[g_ucPos++] = temp;
    }

    if (g_ucPos &gt;= BUFFER_MAXSIZE)
    {
        g_ucPos = 0; //清除位置
    }

}

/*******************************************************************************
* 函 数 名       : main
* 函数功能       : 主函数
* 输    入       : 无
* 输    出         : 无
*******************************************************************************/
void main()
{
    u8 cmd[BUFFER_MAXSIZE];
    u8 aPara1[BUFFER_MAXSIZE];
    u8 aPara2[BUFFER_MAXSIZE];
    UsartInit();  //    串口初始化

    while(1)
    {
        if (g_ucValidFlag == 1)
        {
            //这里提取命令字和参数，然后调用函数
            Uart232SendMsg(receiveData);
            if (0 == Uart232ExtractParams(receiveData, cmd, aPara1, aPara2))
            {
                Uart232CmdProc(cmd, aPara1, aPara2);
            }
            memset(receiveData, 0x0, BUFFER_MAXSIZE);
            memset(cmd, 0x0, BUFFER_MAXSIZE);
            memset(aPara1, 0x0, BUFFER_MAXSIZE);
            memset(aPara2, 0x0, BUFFER_MAXSIZE);
            g_ucValidFlag = 0; //表示可以处理了
        }
    }
}

由于我本人主要在linux上编程学习，这里我选用的是SDCC编译器，语法上与keil有少许差异。用SDCC加上CodeBlocks集成开发环境简直是完美，Codeblocks
IDE本身也是支持创建MCS8051工程的。唯一遗憾的是将程序烧录到开发板中目前没有太好的方法(我用的是STC89C52芯片)，这里我还是用另外一台windows电脑烧录的，用winscp工具将生成好的hex程序从linux拷贝到windows上进行烧录的。下面放几张图片：

dup函数是用来复制一个现有的文件描述符，UNIX-LIKE系统下提供了2个这样函数，原型如下(由unistd.h头文件提供)：
int dup(int filedes);
int dup2(int filedes, int filedes2);

根据APUE书中所讲，dup返回的新文件描述符是可用文件描述符中的最小数值，而dup2可用用filedes2参数指定新描述符的数值。如果filedes2已经打开，则将其关闭。这些函数返回的新文件描述符与被复制的filedes共享同一个文件表项，具体可以查看APUE文档说明。在实际应用项目中，主要是用于标准输出重定向。比如项目中有许多标准输出调试函数（默认启动一个进程时，操作系统默认分配了文件描述符0,1,2给该进程）。有时候需要将这些调试函数输出信息写入到文本文件中去，如何能一次复用现有调试函数而不是推倒重写，那最简单的就是将这些标准输出信息重定向到指定的文本文件中。那就需要用到这2个函数了。
需要注意的是，用这两个函数重定向标准输出时，一定是配合起来用的。由于dup2使用时会关闭filedes2，这里一般指的是标准输出（文件描述符为STDOUT_FILENO，值为1）。需要先用dup函数将其文件描述符保存起来，便于后面重新恢复打印到标准输出中来。另外还有一点就是，如果原有项目中用的是带I/O缓冲函数，即C语言标准库函数，如fprintf,
fread,fwrite,printf等等，需要及时用fflush函数刷新到磁盘文件中去，不然很可能还会显示到标准输出中。实际项目中可以用2个函数封装好之后，注入到现有函数的最前面和结尾，一个函数用于将标准输出重定向到文件，另一个函数用于恢复标准输出。下面是演示代码：
/*
 * =====================================================================================
 *
 *       Filename:  dup.c
 *
 *    Description:  复制一个文件描述符，用于标准输出重定向
 *
 *        Version:  1.0
 *        Created:  2017年08月30日 20时03分45秒
 *       Revision:  none
 *       Compiler:  gcc
 *
 *         Author:  St.John
 *   Organization:  
 *
 * =====================================================================================
 */
#include &lt;stdlib.h&gt;
#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;fcntl.h&gt;

int main()
{
    int newfd;
    int oldfd;
    oldfd = dup(STDOUT_FILENO); /* 把标准输出文件描述符先保存起来 */
    if (oldfd &lt; 0)
    {
        perror(&quot;creat error&quot;);
        exit(0);
    }
    newfd = open(&quot;test.txt&quot;, O_RDWR | O_CREAT | O_TRUNC);
    if (newfd == -1)
    {
        perror(&quot;open failed&quot;);
        exit(0);
    }

    if (dup2(newfd, STDOUT_FILENO) &lt; 0) //这里文件描述符STDOUT_FILENO会关闭，所以先用dup保存起来，便于后面恢复标准输出
    {
        perror(&quot;dup2 error&quot;);
        exit(0);
    }
    printf(&quot;TEXT I am going to sleep now\n&quot;);
    fflush(stdout); //这里需要强制刷新IO缓存，否则可能还会显示到标准输出

    if (dup2(oldfd, STDOUT_FILENO) &lt; 0) 
    {
        perror(&quot;can not dup to stdout&quot;);
        exit(0);
    }

    printf(&quot;Now show on stdout\n&quot;) ; //将标准输出重定向到txt文件中


    return 0;
}

另外还说明一点，复制一个描述符另一种方法就是使用fcntl函数，不过与dup系列函数不同的是，dup2函数是原子操作，而fcntl相当于先关闭文件，然后再复制文件描述符。

